// canopen_slave.cpp - the board's CANopen slave (see canopen_slave.h). The object dictionary is
// generated by the editor (canopen_slave_od.h); the stack is CANopenNode v4.1 with the target
// driver of the runtime's slave. The loop of the runtime's slave thread (openplc-runtime-canopen,
// core/src/drivers/plugins/native/canopen/slave/slave.cpp) runs here from loop(), without LSS.
//
// The board part (CAN controller, program variables, PLC state) is at the top. A host build
// (the runtime fork's CI) defines CANOPEN_SLAVE_HOST and supplies those functions itself.

#include "canopen_slave.h"

