#include <stdint.h>
#include <string.h>

#include "CANopen.h"

extern "C" void co_slave_receive(CO_CANmodule_t *module, const CO_CANrxMsg_t *msg);

// The rows of the generated tables.
typedef struct
{
    uint16_t index;
    uint8_t sub;
    uint8_t dir;   // 0 from the master (%I), 1 to the master (%Q)
    uint8_t exch;  // 0 PDO, 1 SDO, 2 constant
    uint8_t type;  // 0 unsigned, 1 signed, 2 REAL32, 3 REAL64, 4 text
    uint8_t bytes;
    uint8_t flags; // 1 min, 2 max, 4 packed bits
    uint16_t offset;
    uint16_t loc_first;
    uint16_t loc_count;
    uint64_t min;
    uint64_t max;
} co_slave_object_t;

typedef struct
{
    uint16_t index;
    uint16_t first;
    uint16_t count;
} co_slave_app_index_t;

typedef struct
{
    char area; // 'I' or 'Q'
    char size; // 'X', 'B', 'W', 'D' or 'L'
    uint16_t index;
    uint8_t bit;
} co_slave_location_t;

#include "canopen_slave_od.h"

// ---- board part ----

typedef struct
{
    uint32_t id;
    uint8_t dlc;
    uint8_t rtr;
    uint8_t data[8];
} co_board_frame_t;

enum
{
    kBusActive  = 0,
    kBusPassive = 1,
    kBusOff     = 2
};

